const defaults={currency:'USD',rate:18,intent:'Spend with intention',mood:'Okay',trigger:'Boredom',urge:7,urgeAfter:4,checked:false,skipped:284,setAside:90,spent:45,budget:120,challengeType:'Low-buy',categories:['Clothing','Skincare'],rules:['Replace finished essentials','Gifts already planned'],challengeName:'A softer October',challengeCreated:false,challengeDays:30,challengeCompleted:false,activeGoalId:1,goalName:'A weekend away',goalTarget:300,goals:[{id:1,name:'A weekend away',target:300,amount:90,note:'Somewhere slow, with no rush.',contributions:[{date:'October 9',amount:30},{date:'October 5',amount:40},{date:'October 2',amount:20}]}],reminders:{daily:true,cooldown:true,weekly:false},wants:[{id:1,name:'Everyday sneakers',price:96,category:'Clothing',note:'Saw them in a creator’s weekend outfit.',status:'Waiting',hours:46,icon:'shoe'},{id:2,name:'Glow serum',price:32,category:'Skincare',note:'I already have a half-full serum.',status:'Ready',hours:0,icon:'bottle'},{id:3,name:'A little reading lamp',price:45,category:'Home',note:'For my bedside table.',status:'Waiting',hours:20,icon:'lamp'}],owned:[{id:1,name:'My everyday trainers',category:'Clothing',condition:'Still lovely',icon:'shoe'},{id:2,name:'Daily face serum',category:'Skincare',condition:'Half full',icon:'bottle'},{id:3,name:'The unread shelf',category:'Books',condition:'4 stories waiting',icon:'book'}],purchases:[],reflections:[]};
