let screen=screens.some(x=>x.id===location.hash.slice(1))?location.hash.slice(1):'today',view=typeof location.search==='string'&&location.search.includes('view=screens')?'library':'prototype',selectedWant=1,selectedOwned=1,selectedGoal=state.activeGoalId||1,selectedDay=9,search='',wishFilter='All',history=[],draft={},selectedQuestions=[],timerRemaining=90,timerRunning=false,timerInterval=null,shareAmounts=false;
const persist=()=>{try{localStorage.setItem('lessly-demo-v1',JSON.stringify(state))}catch{toast('Your browser could not save this demo locally.')}};
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:state.currency,maximumFractionDigits:2}).format(Number(n)||0);
const goal=()=>state.goals.find(x=>x.id===selectedGoal)||state.goals[0];
const goalAmount=()=>goal()?.amount||0;
const selectGoal=id=>{selectedGoal=Number(id);state.activeGoalId=selectedGoal;state.goalName=goal().name;state.goalTarget=goal().target;persist();};
const want=()=>state.wants.find(x=>x.id===selectedWant)||state.wants[0]||{id:0,name:'Everyday sneakers',price:96,category:'Clothing',note:'A sample want to explore.',status:'Waiting',hours:46,icon:'shoe'};
const owned=()=>state.owned.find(x=>x.id===selectedOwned)||state.owned[0]||{name:'My everyday trainers',category:'Clothing',condition:'Still lovely',icon:'shoe'};
const go=(id)=>{if(!screens.some(x=>x.id===id))return;if(id==='add-goal')draft.goalEdit=screen==='goal-detail';if(id==='profile')draft.profileFrom=screen==='settings'?'settings':'notification-primer';if(id==='notifications')draft.reminderFrom=screen==='notification-primer'?'ready':'settings';history.push(screen);screen=id;view='prototype';location.hash=id;render()};
const back=()=>{screen=history.pop()||'today';location.hash=screen;render()};
const brand=()=>`<span class="brand"><span class="brand-mark">${icon('leaf')}</span>lessly<span class="sr-only"> working name</span></span>`;
const btn=(label,target,variant='',ic='')=>`<button class="button ${variant}" data-go="${target}">${label}${ic?icon(ic):''}</button>`;
const action=(label,name,variant='',ic='')=>`<button class="button ${variant}" data-action="${name}">${label}${ic?icon(ic):''}</button>`;
const link=(label,target)=>`<button class="text-link" data-go="${target}">${label}</button>`;
const illustrationSet={pause:['pause-sculpture','Peach hourglass with a mint sprout'],garden:['growth-garden','A sculptural garden in clay pots'],ritual:['quiet-ritual','Books and tea in a warm clay arch'],companion:['sprout-companion','A patient sprout companion beside an hourglass'],wardrobe:['enough-wardrobe','A small wardrobe with clothes and shoes already owned'],escape:['little-escape','A travel bag, picnic blanket and leafy path'],meal:['simple-meal','A familiar meal and mug at home']};
const art=(name='pause',cls='')=>{const [file,alt]=illustrationSet[name]||illustrationSet.garden;return `<img class="illustration ${cls}" src="assets/${file}.webp" alt="${alt}" width="1254" height="1254" loading="lazy" decoding="async">`};
const motionControl=()=>`<button class="motion-control" data-action="toggle-motion" aria-pressed="${motionEnabled&&!systemReducedMotion}" ${systemReducedMotion?'disabled title="Your device requests reduced motion"':''}>${icon(motionEnabled&&!systemReducedMotion?'pause':'play')}${systemReducedMotion?'Reduced motion':motionEnabled?'Motion on':'Motion off'}</button>`;
