function renderOnboarding(id){const o=onboardingScreens[id],n=Object.keys(onboardingScreens).indexOf(id);return `<div class="onboard-flow"><div class="onboard-content"><div class="onboard-top">${brand()}${link('Explore','today')}</div>${scene(o.art,o.note,o.detail,n===3?'peach':'mint')}<h1 class="hero-title">${o.title}</h1><p class="subtitle">${o.sub}</p><div class="onboard-pagination">${[0,1,2,3].map(i=>`<span class="${i===n?'active':''}"></span>`).join('')}<small>0${n+1} / 04</small></div></div><div class="onboard-actions">${btn(o.label,o.next,'','arrow')}${n===0?btn('Take a look around','today','ghost'):btn('Back',n===1?'welcome':n===2?'intro-pause':'intro-clarity','ghost')}</div></div>`;}
const journeyIllustrations={owned:['wardrobe','Good things.<br>Already yours.','Enjoy the collection you have.'],recovery:['companion','One purchase.<br>A whole story.','Your earlier progress stays.'],'recovery-plan':['companion','A kind next step.','Small is a useful place to start.'],'progress-review':['companion','Your effort stays.','A purchase does not erase it.'],'food-rescue':['meal','An easier default.','Your own familiar meal plan.'],declutter:['wardrobe','One item is enough.','A small space, a sensible next step.'],subscriptions:['ritual','Keep what helps.','A small review of recurring costs.'],commitments:['escape','A little more clarity.','Your own obligations, kept visible.'],buddy:['companion','A little support.','One trusted person, your own choice.'],invite:['companion','Your quiet circle.','Preview what you choose to share.'],'temptation-plan':['companion','Before the rush.','Let your own plan arrive first.'],friction:['wardrobe','Change the easy default.','Small steps you control.'],error:['companion','Your progress stays.','A clear way back to your work.'],'add-goal':['escape','More of what matters.','A reason that is personal to you.']};
function decorateScreen(id,html){const spec=journeyIllustrations[id];if(spec&&!html.includes('journey-illustration')){const marker=html.indexOf('</p>');if(marker>=0)html=html.slice(0,marker+4)+journeyBand(...spec)+html.slice(marker+4)}if(['check-in-done','skip-done','set-aside-done','challenge-complete'].includes(id))html=`<div class="achievement-sparks" aria-hidden="true">${Array.from({length:10},(_,i)=>`<i style="--i:${i};--x:${(i%5-2)*34}px;--y:${-45-i%3*21}px"></i>`).join('')}</div>`+html;return html;}

const reviewDelays={'24 hours':24,'48 hours':48,'72 hours':72,'3 days':72,'7 days':168,'1 week':168};
function safeProductUrl(value){const raw=String(value||'').trim();if(!raw)return '';try{const u=new URL(/^[a-z][a-z0-9+.-]*:/i.test(raw)?raw:'https://'+raw);return ['http:','https:'].includes(u.protocol)&&u.hostname.includes('.')&&!u.username&&!u.password?u.href:'';}catch{return '';}}
const reviewDate=w=>{const d=new Date(w.cooldownUntil);return Number.isFinite(d.getTime())?new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(d):'Choose a review date';};
const waitLabel=w=>w.status==='Ready'?'Ready to revisit':w.hours>=48?Math.ceil(w.hours/24)+' days left':w.hours+'h left';
function reviewPicker(){return `<fieldset class="review-picker"><legend>Remind me to decide in</legend><div>${[['3 days','A little breathing room'],['1 week','Let the impulse settle'],['24 hours','Tomorrow'],['48 hours','Two days']].map(([value,sub])=>`<label><input type="radio" name="cooldown" value="${value}" ${value==='3 days'?'checked':''}><span><b>${value}</b><small>${sub}</small></span>${icon('clock')}</label>`).join('')}</div></fieldset>`;}
const reminderField=(enabled=true)=>`<label class="product-reminder-toggle"><input type="checkbox" name="reminder" value="enabled" ${enabled?'checked':''}><span>${icon('bell')}</span><span><b>Remind me to revisit</b><small>A gentle nudge to decide, with no checkout pressure.</small></span></label>`;
function productLinkCard(w){const url=safeProductUrl(w.productUrl);return url?`<a class="saved-product-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer"><span class="category-icon">${icon('link')}</span><span><b>Open saved product</b><small>${esc(new URL(url).hostname.replace(/^www\./,''))}</small></span>${icon('external')}</a>`:`<button class="saved-product-link" data-go="edit-item"><span class="category-icon">${icon('link')}</span><span><b>Add the product link</b><small>Keep the product here for your later decision.</small></span>${icon('plus')}</button>`;}
function reviewReminderCard(w){return `<section class="review-reminder-card"><div class="row between"><span class="chip">${icon(w.status==='Ready'?'leaf':'clock')}${waitLabel(w)}</span>${link('Change date','edit-item')}</div><h2>${w.status==='Ready'?'Still want this?':'Decide when the wait ends.'}</h2><p>${w.status==='Ready'?'The wait is over. You can let it go, consider buying it, or give it more time.':'Review on <strong>'+reviewDate(w)+'</strong>. There is no need to decide today.'}</p><div class="reminder-status">${icon('bell')} ${w.reminderEnabled?(state.reminders.cooldown?'Reminder requested for this review':'Item reminder saved · Global reminders are off'):'Reminder off · Review date stays saved'}</div></section>`;}
function readyReviewList(){const ready=state.wants.filter(w=>w.status==='Ready');return ready.length?`<section class="ready-review-list"><div class="section-row"><h2 class="section-title">Ready to revisit</h2><span class="chip">${ready.length}</span></div>${ready.slice(0,3).map(w=>`<button class="review-notification" data-action="open-want" data-value="${w.id}"><span class="category-icon">${icon('bell')}</span><span><small>THE WAIT IS OVER</small><b>Still want ${esc(w.name)}?</b><span>Buy thoughtfully, let it go, or wait longer.</span></span>${icon('chevron')}</button>`).join('')}</section>`:'';}
const artFrame=(name='garden',label='A little space to grow')=>`<div class="art-frame art-frame-${name}"><span class="orbit orbit-one" aria-hidden="true"></span><span class="orbit orbit-two" aria-hidden="true"></span>${art(name)}<span class="art-caption">${icon('spark')}${label}</span></div>`;
const challengeRing=(n,label='Your pace')=>`<div class="journey-ring" style="--ring-angle:${Math.min(100,Math.max(0,n))*3.6}deg" role="img" aria-label="${Math.round(n)} percent of challenge time elapsed"><span><b>${challengeDay()}</b><small>of ${challengeLength()} days</small></span></div>`;
const illustratedNote=(heading,sub,name='ritual',target='joy-menu')=>`<button class="illustrated-note" data-go="${target}"><span><span class="overline">${heading}</span><strong>${sub}</strong><span class="round-arrow">${icon('arrow')}</span></span>${art(name)}</button>`;
const header=(title,actionId='',actionIcon='plus')=>`<header class="app-header"><button class="back" data-action="back" aria-label="Go back">${icon('back')}</button><span class="page-title">${title}</span>${actionId?`<button class="icon-btn" data-go="${actionId}" aria-label="${screens.find(s=>s.id===actionId)?.title||'More options'}">${icon(actionIcon)}</button>`:'<span style="width:34px"></span>'}</header>`;
const title=(top,h,sub='')=>`<div class="eyebrow">${top}</div><h1 class="hero-title balance">${h}</h1>${sub?`<p class="subtitle">${sub}</p>`:''}`;
const steps=(n,total=4)=>`<div class="stepbar" aria-label="Step ${n} of ${total}">${Array.from({length:total},(_,i)=>`<span class="${i<n?'done':''}"></span>`).join('')}</div>`;
const field=(label,name,value='',type='text',hint='',placeholder='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${type==='number'?'min="0" step="0.01"':''}>${hint?`<span class="hint">${hint}</span>`:''}</label>`;
const area=(label,name,value='',hint='')=>`<label class="field"><span>${label}</span><textarea name="${name}">${esc(value)}</textarea>${hint?`<span class="hint">${hint}</span>`:''}</label>`;
const select=(label,name,options,current)=>`<label class="field"><span>${label}</span><select name="${name}">${options.map(x=>`<option ${x===current?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`;
const choice=(label,sub,actionName,value,selected=false,ic='')=>`<button class="choice ${selected?'selected':''}" data-action="${actionName}" data-value="${esc(value)}">${ic?`<span class="category-icon">${icon(ic)}</span>`:''}<span class="grow"><span class="item-title">${label}</span>${sub?`<span class="item-sub" style="display:block">${sub}</span>`:''}</span><span class="radio"></span></button>`;
const listRow=(name,sub,target,ic='leaf',end='')=>`<button class="list-row" data-go="${target}"><span class="category-icon">${icon(ic)}</span><span class="grow"><span class="item-title" style="display:block">${name}</span><span class="item-sub">${sub}</span></span>${end?`<span class="small">${end}</span>`:icon('chevron')}</button>`;
const receipt=(label,value)=>`<div class="receipt-line"><span>${label}</span><strong>${value}</strong></div>`;
const checks=items=>`<div class="check-list">${items.map(t=>`<div class="check-line">${icon('check')}<span>${t}</span></div>`).join('')}</div>`;
const submit=(label,ic='arrow')=>`<button class="button" type="submit">${label}${icon(ic)}</button>`;
const form=(id,body)=>`<form data-form="${id}" novalidate>${body}<div class="error-text" role="alert"></div></form>`;
const progress=n=>`<div class="progress" role="progressbar" aria-valuenow="${Math.min(100,Math.round(n))}" aria-valuemin="0" aria-valuemax="100"><span style="width:${Math.min(100,n)}%"></span></div>`;
const topHome=()=>`<header class="app-header">${brand()}<div class="row" style="gap:9px"><button class="icon-btn" data-go="notifications" aria-label="Notifications">${icon('bell')}</button><button class="avatar" data-go="settings" aria-label="Settings">A</button></div></header>`;
const bottomnav=(currentScreen=screen)=>{const active=currentScreen==='today'?'today':currentScreen.startsWith('challenge')||currentScreen==='challenges'?'challenges':['wishlist','item-detail','add-item','edit-item','empty'].includes(currentScreen)?'wishlist':currentScreen==='insights'?'insights':'';return `<nav class="bottomnav" aria-label="Main app navigation">${[['home','Today','today'],['flag','Challenges','challenges'],['pause','Pause','pause'],['heart','Wants','wishlist'],['chart','Patterns','insights']].map(([ic,label,id])=>`<button class="nav-item ${id===active?'active':''} ${id==='pause'?'pause-nav':''}" data-go="${id}">${id==='pause'?`<span class="pause-circle">${icon(ic)}</span>`:icon(ic)}<span>${label}</span></button>`).join('')}</nav>`};
const challengeDay=()=>state.challengeCreated?1:10;
const challengeLength=()=>state.challengeDays||30;
const challengePercent=()=>challengeDay()/challengeLength()*100;
const navScreens=['today','challenges','wishlist','insights','owned','goals'];
function renderBaseScreen(id){const w=want(),o=owned(),allowance=Math.max(0,state.budget-state.spent);const extra=renderCommunity(id);if(extra!==null)return extra;switch(id){
case 'welcome':case 'intro-pause':case 'intro-clarity':case 'intro-grow':return renderOnboarding(id);
case 'intent':return `${header('Your intention')}${title('Let’s begin','What brings<br>you <em>here?</em>','There’s no right answer. Pick what feels like you.')}<div class="spacer"></div>${[['Spend with intention','Buy fewer things I don’t really want.','heart'],['Build a little freedom','Make room for a meaningful goal.','plane'],['Enjoy what I own','Use, repair and rediscover.','wardrobe'],['Feel less overwhelmed','Create a calmer daily rhythm.','leaf']].map(([t,s,i])=>choice(t,s,'intent',t,state.intent===t,i)).join('')}<div class="bottom-action">${btn('Continue','profile','','arrow')}</div>`;
case 'profile':return `${header('Your preferences')}${title('A personal perspective','Make it<br><em>your own.</em>','A few details help put your choices in context.')} ${form('profile',select('Your currency','currency',['USD','GBP','EUR','PKR','CAD','AUD'],state.currency)+field('Take-home hourly rate (optional)','rate',state.rate,'number','Use an estimate after tax. Leave blank to hide work hours. Changing currency relabels demo amounts; it does not convert them.')+`<div class="modal-note">${icon('lock')} No bank connection or account is needed for this prototype. All demo changes stay in this browser.</div><div class="spacer"></div>`+submit('Continue'))}`;
case 'notification-primer':return `${header('Gentle reminders')}<div class="onboarding"><div class="success-mark" style="background:#f5dfd3;margin-top:55px">${icon('bell')}</div>${title('Only a little nudge','A reminder.<br><em>Never</em> a guilt trip.','A daily check-in and a heads-up when a want has finished waiting. Choose what feels useful.')}<div class="spacer"></div>${btn('Choose my reminders','notifications','','arrow')}${btn('Maybe later','ready','ghost')}<p class="footer-note">System notification permission would be requested<br>after you choose reminders in the real app.</p></div>`;
case 'ready':return `${header('A fresh beginning')}<div class="onboarding">${scene('companion','Your own kind of beginning.','A small first step.','mint')}${title('You’ve made room','Your softer<br>start is <em>here.</em>',esc(state.intent)+'. Let’s make your first small choice.')}<div class="spacer"></div>${btn('Try a gentle seven-day start','starter','','leaf')}${btn('Create my own challenge','challenge-type','ghost')}${btn('Let me look around','today','ghost')}</div>`;
case 'today':return `${topHome()}<div class="day-label"><span class="eyebrow">Saturday, October 10</span><span class="live-label"><i></i> DEMO DAY</span></div><div class="home-heading"><h1 class="hero-title">Less buying.<br><em>More living.</em></h1><span class="hand-drawn-star" aria-hidden="true">✳</span></div><button class="save-product-invitation" data-go="add-item"><span class="category-icon">${icon('link')}</span><span><b>Saw something you like?</b><small>Save the link. Decide in 3 days or a week.</small></span>${icon('plus')}</button>${readyReviewList()}<section class="daily-landscape"><div class="landscape-copy"><span class="overline">${esc(state.challengeName)}</span><h2>Good things<br>need a little<br><em>room.</em></h2><button class="landscape-link" data-go="challenge-detail">My challenge ${icon('arrow')}</button></div>${art('garden')}<div class="landscape-footer"><span>${icon('leaf')} Day ${challengeDay()} of ${challengeLength()}</span><span>Your pace, always.</span></div></section><div class="money-duo"><div><span class="overline">Cost you skipped</span><strong>${money(state.skipped)}</strong><span class="tiny muted">Purchase cost · Not savings</span></div><div><span class="overline">Actually set aside</span><strong>${money(state.setAside)}</strong><span class="tiny muted">Money you confirmed</span></div></div><div class="section-row"><h2 class="section-title">One small thing today</h2>${link('My rhythm','progress-review')}</div><button class="daily-checkin" data-go="check-in"><span class="category-icon peach">${icon(state.checked?'check':'sun')}</span><span class="grow"><strong>${state.checked?'You showed up today.':'How is your heart today?'}</strong><span>${state.checked?'Revisit your saved reflection.':'A 20-second check-in. All moods welcome.'}</span></span><span class="round-arrow">${icon('arrow')}</span></button><div class="pause-invitation"><div><span class="overline">A want can wait</span><h3>Keep the choice.<br><em>Lose the rush.</em></h3>${link('Take a little pause','pause')}</div>${art()}</div><div class="section-row"><h2 class="section-title">Beyond the checkout</h2>${link('My little joys','joy-menu')}</div>${illustratedNote('Already yours','A chapter. A cup.<br>A little quiet.','ritual','joy-menu')}<div class="section-row"><h2 class="section-title">Your room to grow</h2>${link('All goals','goals')}</div>${listRow(esc(state.goalName),money(goalAmount())+' of '+money(state.goalTarget)+' actually set aside','goal-detail','plane')}`;
case 'check-in':return `${header('Daily check-in','calendar','calendar')}${title('October 10','How is today<br><em>feeling?</em>','Just a moment to notice. You don’t need a perfect answer.')}<div class="mood-grid">${[['Heavy','sad'],['Low','sad'],['Okay','neutral'],['Good','smile'],['Lovely','smile']].map(([m,i])=>`<button class="mood ${state.mood===m?'selected':''}" data-action="mood" data-value="${m}"><span class="mood-face">${icon(i)}</span>${m}</button>`).join('')}</div>${form('check-in',select('Any purchases today?','spending',['No purchases','Only planned purchases','An unplanned purchase'],state.checkInSpending||'No purchases')+area('One small reflection (optional)','reflection',state.checkInNote||'','What felt easy, or what felt tricky?')+submit(state.checked?'Update my check-in':'Save my check-in','check'))}<p class="footer-note">Your check-in is private. Spending days still count as showing up.</p>`;
case 'check-in-done':return `${header('You showed up')}<div class="center">${scene('companion','A little choice, acknowledged.','Your progress stays.','mint')}${title('A small good thing','Every check-in<br><em>counts.</em>','Today is part of your story. Thank you for noticing.')}<div class="week-grid">${['M','T','W','T','F','S','S'].map((d,i)=>`<div class="week-day">${d}<span class="${i===5?'active':''}">${i<6?icon('check'):'·'}</span></div>`).join('')}</div><div class="card mint-card"><div class="overline">Your consistency</div><div class="metric small">${weekCheckins()} of 7 demo days</div><p class="small muted">A rhythm you can return to. No streak to lose.</p></div><div class="spacer"></div>${btn('Back to my day','today','','arrow')}${btn('See my calendar','calendar','ghost')}</div>`;
case 'calendar':return `${header('Your calendar')}${title('Your real life','Every day<br>has a <em>place.</em>','Green means you checked in without a purchase. Peach means you logged spending. Both are progress.')}<div class="section-row"><h2 class="section-title">October 2026</h2><span class="chip">Sample month</span></div><div class="calendar-grid">${['M','T','W','T','F','S','S'].map(x=>`<span class="weekday">${x}</span>`).join('')}${'<span></span>'.repeat(3)}${Array.from({length:31},(_,i)=>`<button class="calendar-day ${[1,2,3,5,6,8,9].includes(i+1)||((i+1)===10&&state.checked)?'checked':''} ${[4,7].includes(i+1)?'buy':''} ${i===9?'today':''}" data-action="open-day" data-value="${i+1}" ${i>9?'disabled':''}>${i+1}</button>`).join('')}</div><div class="row small muted"><span class="dot"></span> Checked in <span class="dot" style="background:var(--peach);margin-left:13px"></span> Purchase day</div><div class="spacer"></div><div class="card mint-card"><div class="row between"><span class="small">Check-ins this month</span><strong>${checkinCount()} / 10</strong></div></div>${btn('Check in today','check-in','','sun')}`;
case 'day-detail':return `${header('Your reflection')}${title(new Date(2026,9,selectedDay).toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'}),'A day with<br>a little <em>space.</em>',selectedDay===10&&state.checked?'Your saved check-in.':'Sample reflection from your calendar.')}<div class="card"><div class="row"><span class="category-icon">${icon('smile')}</span><div><div class="item-title">Feeling good</div><div class="item-sub">No purchases · Checked in at 8:42 PM</div></div></div><div class="spacer"></div><p class="quote">“${esc(selectedDay===10&&state.checked?state.checkInNote||'I showed up today.':'Wore my old trainers on a long walk. They still feel great.')}”</p></div><div class="card mint-card"><div class="overline">A thoughtful choice</div><div class="item-title" style="margin-top:9px">Let a ${money(32)} want keep waiting</div><p class="small muted">You noticed that you already had something similar.</p></div>${btn('Back to the calendar','calendar','outline')}`;
case 'challenges':return `${topHome()}${title('A promise, not a punishment','Your pace.<br><em>Your rules.</em>','Make it small enough to live with.')}<div class="section-row"><h2 class="section-title">Your current chapter</h2>${link('New chapter','challenge-type')}</div><button class="challenge-chapter" data-go="challenge-detail"><span class="chapter-number">01 / IN PROGRESS</span><div class="row between"><div><span class="chip">${icon('flag')}${state.challengeType}</span><h2>${esc(state.challengeName)}</h2><p>${state.categories.map(esc).join(' · ')}</p></div>${challengeRing(challengePercent())}</div><div class="chapter-footer"><span>${state.challengeType==='Low-buy'?money(allowance)+' allowance left':'Essentials are welcome'}</span><span class="round-arrow">${icon('arrow')}</span></div></button>${illustratedNote('Small is a great start','Seven days.<br>One kinder habit.','garden','starter')}<div class="section-row"><h2 class="section-title">Make it work for real life</h2></div><div class="tool-grid"><button data-go="pockets"><span class="category-icon">${icon('wallet')}</span><strong>Allowance<br>pockets</strong><small>Room for a little fun.</small>${icon('arrow')}</button><button data-go="rule-check"><span class="category-icon peach">${icon('leaf')}</span><strong>Essential<br>exceptions</strong><small>Needs come first.</small>${icon('arrow')}</button></div>${listRow('Before the next sale','Let your rules arrive before the deals.','temptation-plan','calendar')}${listRow('A quiet accountability buddy','A little support from someone you trust.','buddy','users')}`;
case 'challenge-type':return `${header('A new challenge')}${steps(1)}${title('Start where you are','What feels<br><em>realistic?</em>','A useful challenge has room for real life.')}<div class="spacer"></div>${choice('No-buy','Pause non-essential purchases in your chosen categories.','challengeType','No-buy',state.challengeType==='No-buy','pause')}${choice('Low-buy','Set an allowance and buy with intention.','challengeType','Low-buy',state.challengeType==='Low-buy','wallet')}<div class="card mint-card"><p class="small muted">Essentials, replacements and planned exceptions can be part of either challenge.</p></div>${btn('Choose my focus','challenge-categories','','arrow')}`;
case 'challenge-categories':return `${header('Choose your focus')}${steps(2)}${title('Keep it manageable','Where could you<br>buy a little <em>less?</em>','Choose one or a few categories. You can change them later.')}<div class="tag-list">${['Clothing','Skincare','Home','Books','Tech','Takeaway','Hobbies','Everything non-essential'].map(t=>`<button class="tag-button ${state.categories.includes(t)?'selected':''}" data-action="category" data-value="${t}">${t}</button>`).join('')}</div><div class="card mint-card">${icon('leaf')}<p class="small muted" style="margin-top:9px">A focused challenge is often easier to keep than changing everything at once.</p></div><div class="bottom-action">${action('Set my rules','categories-next','','arrow')}</div>`;
case 'challenge-rules':return `${header('Rules & exceptions')}${steps(3)}${title('Your definition of enough','Leave room for<br><em>real life.</em>','Choose exceptions that help the challenge fit you.')}<div class="spacer"></div>${['Replace finished essentials','Gifts already planned','Health and safety needs','Repair before replacing'].map(t=>choice(t,'','rule',t,state.rules.includes(t))).join('')}${form('rules',area('A personal rule (optional)','customRule',draft.customRule||'','Example: Wait 48 hours before every non-essential purchase.')+submit('Continue'))}`;
case 'challenge-budget':return `${header('A little structure')}${steps(4)}${title('Give it a shape','A plan you can<br><em>actually</em> keep.','Choose a timeframe and a name that feels good.')} ${form('budget',field('Challenge name','name',state.challengeName)+select('Duration','duration',['7 days','14 days','30 days','60 days'],'30 days')+(state.challengeType==='Low-buy'?field('Total allowance ('+state.currency+')','budget',state.budget,'number','For the entire challenge, across your chosen categories.'):'<div class="card mint-card"><p class="small muted">Non-essential purchases will be paused. Your selected exceptions remain welcome.</p></div>')+submit('Review my plan'))}`;
case 'challenge-review':return `${header('Review your challenge')}${title('Ready when you are','Your softer<br><em>commitment.</em>','Everything here is yours to adjust.')}<div class="card dark-card"><div class="chip">${icon('flag')} ${state.challengeType}</div><h2 class="quote" style="margin:18px 0">${esc(state.challengeName)}</h2><div class="subtitle">${state.categories.map(esc).join(' · ')}</div><div class="stats-divider"></div>${receipt('Duration',draft.duration||'30 days')}${state.challengeType==='Low-buy'?receipt('Allowance',money(state.budget)):''}</div><div class="section-row"><h2 class="section-title">Your exceptions</h2>${link('Edit','challenge-rules')}</div>${checks(state.rules.map(esc))}${draft.customRule?`<div class="card"><p class="small">${esc(draft.customRule)}</p></div>`:''}<div class="bottom-action">${action('Begin my challenge','begin-challenge','','leaf')}</div>`;
case 'challenge-detail':return `${header('Your challenge','edit-rules','edit')}${title(state.challengeType+' / Your personal plan',esc(state.challengeName),`Day ${challengeDay()} of ${challengeLength()} · `+state.categories.map(esc).join(' & '))}<div class="card dark-card"><div class="row between"><div><div class="overline">Days you showed up</div><div class="metric">${state.challengeCreated?(state.checked?1:0):checkinCount()}<span style="font-size:18px;opacity:.5"> / ${challengeDay()}</span></div></div><span class="chip">${icon('leaf')} ${state.challengeCreated?'A fresh beginning':Math.round(checkinCount()/10*100)+'% check-in consistency'}</span></div>${progress(challengePercent())}<p class="tiny" style="margin-top:10px;opacity:.7">${challengeLength()-challengeDay()} days left · Purchases don’t reset your progress.</p></div>${state.challengeType==='Low-buy'?`<div class="two-col"><div class="card"><div class="overline">Spent so far</div><div class="metric small">${money(state.spent)}</div><div class="tiny muted">Of ${money(state.budget)} allowance</div></div><div class="card mint-card"><div class="overline">Still available</div><div class="metric small">${money(allowance)}</div><div class="tiny muted">${state.spent>state.budget?'Allowance exceeded — review kindly':'For intentional choices'}</div></div></div>`:''}<div class="section-row"><h2 class="section-title">Your personal rules</h2>${link('Adjust','edit-rules')}</div>${checks(state.rules.map(esc))}<div class="button-row">${btn('Log a purchase','purchase-log','outline')}${btn('Daily check-in','check-in')}</div><div class="section-row"><h2 class="section-title">Looking ahead</h2></div>${listRow('A sale is coming','Make a plan before the countdown.','temptation-plan','calendar')}${btn('The progress I keep','progress-review','outline')}${btn('Preview completion','challenge-complete','ghost')}`;
case 'edit-rules':return `${header('Adjust your challenge')}${title('It can evolve','A rule that<br><em>fits better.</em>','Changes apply from today. Your past check-ins stay part of your story.')} ${form('edit-rules',field('Challenge name','name',state.challengeName)+field('Allowance ('+state.currency+')','budget',state.budget,'number','Only applies to a low-buy challenge.')+area('My rules & exceptions','rules',state.rules.join('\n'),'One rule per line.')+submit('Save my changes','check'))}`;
case 'challenge-complete':return `${header('A thoughtful finish')}<div class="center">${art('garden')}${title('Your 30-day chapter','Look at what<br>you made <em>room for.</em>','Completion screen concept · Your actual challenge is still in progress.')}<div class="two-col"><div class="card"><div class="overline">Cost skipped</div><div class="metric small">${money(state.skipped)}</div></div><div class="card mint-card"><div class="overline">Actually set aside</div><div class="metric small">${money(state.setAside)}</div></div></div><div class="spacer"></div>${btn('Reflect on my progress','weekly-review','','leaf')}${btn('Share a little win','share-card','ghost')}</div>`;
case 'wishlist':return `${topHome()}${title('Your waiting room','A want, with<br><em>room to breathe.</em>','Save the product link. Choose a review date. Decide later.')}<div class="waiting-summary"><span class="waiting-orbit">${icon('clock')}</span><span><strong>${state.wants.length} thoughts, quietly waiting.</strong><small>There’s no deadline to want them.</small></span><button class="icon-btn" data-go="add-item" aria-label="Save a product link">${icon('plus')}</button></div><div class="segmented">${['All','Waiting','Ready'].map(t=>`<button class="${wishFilter===t?'active':''}" data-action="filter" data-value="${t}">${t==='Ready'?'To revisit':t}</button>`).join('')}</div><div class="waiting-collection">${state.wants.filter(x=>wishFilter==='All'||x.status===wishFilter).map((x,i)=>`<button class="waiting-item" data-action="open-want" data-value="${x.id}"><div class="waiting-object object-${x.icon}"><span class="object-index">${String(i+1).padStart(2,'0')}</span><span class="wish-art ${x.icon==='shoe'?'green':x.icon==='bottle'?'peach':''}">${icon(x.icon)}</span><span class="object-price">${money(x.price)}</span></div><div class="waiting-info"><div><h2>${esc(x.name)}</h2><p>${esc(x.category)}</p></div><span class="round-arrow">${icon('arrow')}</span></div><div class="waiting-status"><span class="chip">${icon(x.status==='Ready'?'leaf':'clock')}${waitLabel(x)}</span><span class="tiny muted">${x.status==='Ready'?'Still want it?':'Review '+reviewDate(x)}</span></div></button>`).join('')||`<div class="center">${art('pause','small')}<p class="subtitle">Nothing in this view. A little empty space is lovely.</p></div>`}</div><div class="spacer"></div>${btn('Save a product for later','add-item','','plus')}${btn('Remember what I already own','owned','ghost')}`;
case 'add-item':return `${header('Save a product')}${title('Save now. Decide later.','A link today.<br><em>A choice later.</em>','Saw something you want? Save it here and choose when to revisit it.')}<div class="capture-steps"><span>${icon('link')} Save</span>${icon('chevron')}<span>${icon('clock')} Wait</span>${icon('chevron')}<span>${icon('leaf')} Decide</span></div>${form('add-item',field('Product link (optional)','productUrl',draft.newWantUrl||'','url','Paste the shop or product page. No purchase is made.','https://shop.com/product')+field('What caught your eye?','name',draft.newWantName||'','text','','Everyday sneakers')+field('Price ('+state.currency+')','price',draft.newWantPrice||'','number')+select('Category','category',['Clothing','Skincare','Home','Books','Tech','Hobbies','Takeaway','Gifts'],'Clothing')+reviewPicker()+reminderField()+area('Why do you want it? (optional)','note','','A feeling, a need, or a moment you noticed.')+submit('Save product & review date','clock'))}<p class="footer-note">Prototype: your link and review date save here. Device notification delivery is not connected yet.</p>`;
case 'item-detail':return `${header('Your saved product','edit-item','edit')}<div class="item-hero">${icon(w.icon)}<span class="chip">${icon('clock')}${waitLabel(w)}</span></div>${title(esc(w.category),esc(w.name),'Saved for a later decision. It stays your choice.')}<div class="row between" style="margin:16px 0"><div class="metric">${money(w.price)}</div>${link('See the time price','work-hours')}</div>${reviewReminderCard(w)}${productLinkCard(w)}${w.status==='Ready'?`<div class="stack decision-actions">${action('I no longer want it','skip-want','','leaf')}${btn('I still want it · review before buying','decision-check','outline','bag')}<div class="two-col">${action('Wait 3 more days','wait-three','secondary','clock')}${action('Wait another week','wait-week','secondary','clock')}</div></div>`:btn('Let it wait','wishlist','','check')+btn('Review it early','decision-check','ghost')}<div class="card"><div class="overline">Why it caught your eye</div><p class="small" style="margin-top:9px">${esc(w.note||'No note yet. You can add one whenever you like.')}</p></div><button class="card choice mint-card" data-go="compare-owned"><span class="category-icon">${icon('wardrobe')}</span><span class="grow"><span class="item-title">Could something you own do this?</span><span class="item-sub" style="display:block">Rediscover your personal inventory.</span></span>${icon('chevron')}</button>${btn('Does a replacement fit my rules?','rule-check','outline')}${btn('Was the sale doing the deciding?','deal-check','ghost')}<p class="footer-note">The review date is saved locally. Device notifications will be connected in the native app.</p>`;
case 'edit-item':return `${header('Edit saved product')}${form('edit-item',field('Product link (optional)','productUrl',w.productUrl||'','url','','https://shop.com/product')+field('Name','name',w.name)+field('Price ('+state.currency+')','price',w.price,'number')+select('Category','category',['Clothing','Skincare','Home','Books','Tech','Hobbies','Takeaway','Gifts'],w.category)+select('Review date','cooldown',['Keep current review date','24 hours','48 hours','3 days','1 week'],'Keep current review date')+`<p class="current-review-date">Currently: ${reviewDate(w)}</p>`+reminderField(w.reminderEnabled)+area('A little context','note',w.note)+submit('Save changes','check'))}<div class="spacer"></div>${action('Remove from waiting room','delete-want','ghost','trash')}<p class="footer-note">Removing an item does not count its price as skipped spending.</p>`;
case 'decision-check':return `${header('Before you decide')}${title('A little clarity','Would it still<br>feel <em>right tomorrow?</em>','There’s no score to pass. These questions help you notice.')}<div class="card mint-card row"><span class="wish-art">${icon(w.icon)}</span><div><div class="item-title">${esc(w.name)}</div><div class="small muted">${money(w.price)} · ${esc(w.category)}</div></div></div>${['I know when and how I’ll use it.','I don’t already own a good alternative.','It fits my challenge rules or an exception.','I can afford it within my allowance.'].map((t,i)=>choice(t,'','question',String(i),selectedQuestions.includes(i))).join('')}${btn('See my options','decision-result','','arrow')}<p class="footer-note">Checked answers support reflection. They never guarantee a good purchase.</p>`;
case 'work-hours':{const hours=state.rate>0?w.price/state.rate:null;return `${header('The time price')}${title('Another way to see it','Your time<br>is <em>valuable.</em>','What could this want mean in hours of work?')}<div class="card dark-card center" style="padding:32px 20px;margin:25px 0"><div class="overline">${esc(w.name)} · ${money(w.price)}</div><div class="metric" style="font-size:54px;margin:20px 0">${hours===null?'—':Math.floor(hours)+'h '+Math.round((hours%1)*60)+'m'}</div><p class="subtitle">${hours===null?'Add an optional rate below.':'At your '+money(state.rate)+'/hour take-home estimate.'}</p></div>${form('rate',field('My take-home hourly rate ('+state.currency+')','rate',state.rate||'','number','An approximate perspective, not a calculation of affordability.')+submit('Update my perspective','check'))}<div class="spacer"></div>${btn('Back to my decision','decision-result','outline')}`;}
case 'decision-result':return `${header('Your choice')}${title('You get to decide','What feels<br><em>intentional?</em>','You reflected on '+selectedQuestions.length+' of 4 prompts. There’s no perfect answer.')}<div class="card">${receipt('The want',esc(w.name))}${receipt('Price',money(w.price))}${receipt('Your remaining allowance',money(allowance))}<div class="modal-note">${w.price>allowance?'This price exceeds your current low-buy allowance. You can wait, let it go, or log a purchase honestly.':'Consider your own rules and any essential exception before deciding.'}</div></div><div class="stack">${action('I’m letting this want go','skip-want','','leaf')}${btn('I’ll buy it intentionally','purchase-log','outline','bag')}${btn('Check an essential exception','rule-check','secondary')}<div class="two-col">${action('Wait 3 more days','wait-three','secondary','clock')}${action('Wait another week','wait-week','secondary','clock')}</div></div><p class="footer-note">No purchase is made here. You choose and log what happens outside the app.</p>`;
case 'purchase-log':return `${header('Log a purchase')}${title('Real life belongs here','A purchase.<br>A little <em>context.</em>','Planned spending doesn’t erase your progress.')} ${form('purchase',field('What did you buy?','name',w.name)+field('Amount ('+state.currency+')','amount',w.price,'number')+select('Category','category',['Clothing','Skincare','Home','Books','Tech','Hobbies','Takeaway','Gifts'],w.category)+select('How does it fit your plan?','kind',['Planned purchase','Allowed exception','Unplanned purchase'],draft.exceptionPurchase?'Allowed exception':'Planned purchase')+area('A note for future you (optional)','note',draft.exceptionPurchase?state.ruleDecisions.at(-1)?.rule||'':'')+field('Return-by date from the retailer (optional)','returnBy','','date','Use the actual date from the receipt or policy, if relevant.')+`<div class="modal-note">This updates your demo spending total. It does not connect to your bank or make a purchase.</div><div class="spacer"></div>`+submit('Save purchase','check'))}`;
case 'skip-done':return `${header('A little space')}<div class="center"><div class="success-mark">${icon('leaf')}</div>${title('A thoughtful choice','You let<br>a want <em>go.</em>','There’s a little more space in your day.')}<div class="card mint-card"><div class="overline">Purchase cost skipped</div><div class="metric">${money(draft.skippedPrice||96)}</div><p class="small muted">This is spending you avoided.<br>It becomes actual savings only if you set money aside.</p></div>${btn('I actually set money aside','set-aside','','arrow')}${btn('That’s enough for today','today','ghost')}</div>`;
case 'pause':return `${header('The pause studio')}<div class="pause-experience"><span class="pill-banner">${icon('pause')} A MOMENT THAT IS YOURS</span><h1 class="hero-title">Keep the choice.<br><em>Lose the rush.</em></h1><p class="subtitle">The want can wait.<br>Let yourself catch up with the moment.</p>${artFrame('companion','90 seconds, with no pressure')}<div class="pause-duration"><span>01:30</span><div><strong>A guided little pause</strong><small>Notice. Breathe. Choose.</small></div></div>${btn('Make a little space','trigger','','arrow')}${btn('I already bought something','recovery','ghost')}<p class="footer-note">Your decision is always yours.<br>A reflection tool, not treatment.</p></div>`;
case 'trigger':return `${header('Name the moment')}${title('Before we pause','What is this urge<br><em>asking for?</em>','A feeling isn’t a problem. It’s useful information.')}<div class="tag-list">${['Boredom','Stress','A reward','A sale','Social media','Feeling left out','A real need','Not sure'].map(t=>`<button class="tag-button ${state.trigger===t?'selected':''}" data-action="trigger" data-value="${t}">${t}</button>`).join('')}</div><div class="field"><span>How strong is the urge right now?</span><input class="range" type="range" min="1" max="10" value="${state.urge}" data-range="urge" aria-label="Urge strength"><div class="row between small muted"><span>A passing thought</span><strong id="urge-label">${state.urge}/10</strong><span>Very strong</span></div></div><div class="bottom-action">${action('Take 90 seconds','start-timer','','pause')}</div><p class="footer-note">You can stop or skip the timer whenever you like.</p>`;
case 'timer':return `${header('A little breathing room')}<div class="center">${title('No rush','Let the moment<br><em>soften.</em>','Breathe at a comfortable pace. Nothing to force.')}<div class="timer-wrap"><div class="timer-ring" style="--timer-angle:${(90-timerRemaining)/90*360}deg"><div class="timer-center"><span class="eyebrow breathe">A little space</span><div class="timer-time" id="timer-time">${formatTime(timerRemaining)}</div><span class="tiny">${timerRemaining===0?'You made room for a choice.':'Notice your feet. Relax your shoulders.'}</span></div></div></div><div class="button-row">${action(timerRunning?'Pause timer':'Resume timer','toggle-timer','outline',timerRunning?'pause':'play')}${btn(timerRemaining===0?'Reflect now':'Finish early','reflection','','arrow')}</div><p class="footer-note">A countdown, not a test.<br>Leaving this screen pauses the timer.</p></div>`;
case 'reflection':return `${header('After the pause')}${title('Notice what changed','How does the<br>want feel <em>now?</em>','It’s okay if the feeling hasn’t changed. You still created a moment of choice.')}<div class="card mint-card"><div class="row between"><span class="small">Before the pause</span><strong>${state.urge}/10</strong></div></div><div class="field"><span>My urge right now</span><input class="range" type="range" min="1" max="10" value="${state.urgeAfter}" data-range="urgeAfter" aria-label="Urge after the pause"><div class="row between small muted"><span>A passing thought</span><strong id="urgeAfter-label">${state.urgeAfter}/10</strong><span>Very strong</span></div></div><div class="card"><p class="quote">“A feeling can be here without becoming a purchase.”</p></div>${action('Save my reflection','save-pause','','check')}${btn('See another way','alternatives','ghost')}`;
case 'alternatives':return `${header('Another way')}${title('You have options','Meet the feeling.<br>Skip the <em>checkout.</em>','You named '+esc(state.trigger.toLowerCase())+'. Try a small alternative that feels doable.')}<div class="spacer"></div>${listRow('Rediscover something I own','Could I use what is already here?','owned','wardrobe')}${listRow('Put the want in my waiting room','Let the decision belong to another day.','add-item','clock')}${listRow('My personal no-spend menu','Something that fits my energy today.','joy-menu','sun')}${listRow('A meal before the delivery app','An easy plan from food I already have.','food-rescue','cup')}${listRow('Make shopping less automatic','My personal friction checklist.','friction','lock')}${listRow('Ask a quiet accountability buddy','A little support, without a public feed.','buddy','users')}<div class="spacer"></div>${btn('Back to my day','today','outline')}`;
case 'recovery':return `${header('A fresh start')}${title('You’re still doing okay','One purchase<br>isn’t your <em>whole story.</em>','Let’s understand the moment, without turning it into a punishment.')}<div class="card peach-card"><p class="quote">“Progress is a place you can come back to.”</p></div>${form('recovery',select('What was happening?','trigger',['Boredom','Stress','A reward','A sale','Social media','Feeling left out','Not sure'],state.trigger)+area('What could help next time?','note','','A small step, not a new rule for your whole life.')+submit('Make a kind reset plan'))}${btn('Log the purchase honestly','purchase-log','ghost')}`;
case 'recovery-plan':return `${header('Your next small step')}${title('A return, not a reset','Make the next<br>moment <em>easier.</em>','Your consistency stays. Start from where you are.')}<div class="card mint-card"><div class="overline">Your personal plan</div><p class="quote" style="margin-top:10px">${esc(draft.recoveryNote||'When the urge comes, step away for a short walk before deciding.')}</p></div><div class="timeline"><div class="event"><div class="item-title">Notice</div><p class="item-sub">Name the feeling: ${esc(state.trigger)}.</p></div><div class="event"><div class="item-title">Create space</div><p class="item-sub">Try a 90-second pause, or wait until tomorrow.</p></div><div class="event"><div class="item-title">Choose kindly</div><p class="item-sub">Adjust a rule if it wasn’t realistic.</p></div></div>${btn('Return to my day','today','','leaf')}${btn('See the progress I still have','progress-review','outline')}${btn('Adjust my rules','edit-rules','ghost')}`;
case 'owned':return `${topHome()}${title('Your enough collection','Good things<br>are <em>already here.</em>','A small reminder of what you can use, enjoy and rediscover.')}<div class="section-row"><h2 class="section-title">Things I own</h2>${link('Add an item','add-owned')}</div>${state.owned.map(x=>`<button class="card choice" data-action="open-owned" data-value="${x.id}"><span class="wish-art ${x.icon==='shoe'?'green':'peach'}">${icon(x.icon)}</span><span class="grow"><span class="item-title">${esc(x.name)}</span><span class="item-sub" style="display:block">${esc(x.category)} · ${esc(x.condition)}</span></span>${icon('chevron')}</button>`).join('')}<div class="card mint-card insight-callout">${icon('spark')}<span>Your own inventory makes alternatives personal. It only contains items you add.</span></div>${btn('Add something I own','add-owned','outline','plus')}${btn('My use-up shelf','use-up','secondary')}${btn('One item, less overwhelm','declutter','ghost')}`;
case 'add-owned':return `${header('Your enough collection')}${title('A little rediscovery','What is<br><em>already yours?</em>','Start with something you often forget you have.')} ${form('owned',field('Item name','name','','text','','My everyday trainers')+select('Category','category',['Clothing','Skincare','Home','Books','Tech','Hobbies','Takeaway','Gifts'],'Clothing')+field('Condition or a useful note','condition','','text','','Still lovely, just needs a clean')+submit('Add to my collection','plus'))}<p class="footer-note">Photo upload is a future feature. This prototype uses category illustrations.</p>`;
case 'owned-detail':return `${header('Rediscover this')}<div class="item-hero">${icon(o.icon)}</div>${title(esc(o.category),esc(o.name),esc(o.condition))}<div class="card mint-card"><div class="overline">A little care goes a long way</div><p class="quote" style="margin-top:12px">${o.category==='Clothing'?'Clean it. Style it differently. Wear it somewhere new.':o.category==='Skincare'?'Finish what you have before opening something new.':'Give it a place in your day again.'}</p></div>${action('I’ll use this today','use-owned','','check')}${btn('Explore my waiting room','wishlist','ghost')}`;
case 'compare-owned':{const available=state.owned.filter(x=>!['Finished','Unsuitable or unsafe','Given away'].includes(x.useStatus));const alt=available.find(x=>x.category===w.category)||available[0];return `${header('An alternative is here')}${title('Before something new','Could this<br>do the <em>same job?</em>','An alternative from your own collection. You decide if it meets your need.')}<div class="two-col" style="margin:22px 0"><div class="card center"><span class="wish-art" style="margin:0 auto 15px">${icon(w.icon)}</span><div class="overline">The want</div><div class="item-title" style="margin-top:9px">${esc(w.name)}</div><div class="small muted">${money(w.price)}</div></div><div class="card mint-card center"><span class="wish-art green" style="margin:0 auto 15px">${icon(alt?.icon||'wardrobe')}</span><div class="overline">Already yours</div><div class="item-title" style="margin-top:9px">${esc(alt?.name||'Add an item you own')}</div><div class="small muted">${esc(alt?.condition||'Build your inventory')}</div></div></div><div class="card"><p class="small muted">${alt?.category===w.category?'A category match from suitable active items, not an automated judgment. Think about comfort, condition and purpose.':'No item in the same category yet. Add one to make this comparison more useful.'}</p></div>${action(alt?'I’ll enjoy what I have':'I’m letting the want go','skip-want','','leaf')}${btn('I still want to reflect','decision-check','outline')}${btn('Add a better alternative','add-owned','ghost')}`;}
case 'goals':return `${topHome()}${title('What matters to you','Less stuff.<br><em>More possibility.</em>','A purpose for money you actually set aside.')}<div class="goal-landscape">${art('escape')}<div><span class="overline">Actually set aside</span><strong>${money(state.setAside)}</strong><span>Across your personal goals · Self-reported</span></div></div><div class="section-row"><h2 class="section-title">Your little freedom funds</h2>${link('New goal','add-goal')}</div>${state.goals.map(g=>`<button class="goal-fund" data-action="open-goal" data-value="${g.id}"><div class="row"><span class="goal-art">${icon('plane')}</span><div class="grow"><h2>${esc(g.name)}</h2><p>${esc(g.note||'A meaningful little goal.')}</p></div>${icon('arrow')}</div><div class="goal-fund-amount"><strong>${money(g.amount)}</strong><span>of ${money(g.target)}</span><b>${Math.round(g.amount/g.target*100)}%</b></div>${progress(g.amount/g.target*100)}<span class="tiny muted">Money you confirmed, not the cost of skipped wants.</span></button>`).join('')}${btn('I set some money aside','set-aside','','plus')}<p class="footer-note">Money stays with you. Lessly records your confirmations.</p>`;
case 'add-goal':return `${header('A meaningful goal')}${title('A reason to make room','What are you<br><em>saving for?</em>','Small freedom, a useful cushion, or something that lasts.')} ${form('goal',field('My goal','name',draft.goalEdit?state.goalName:'')+field('Target amount ('+state.currency+')','target',draft.goalEdit?state.goalTarget:'','number')+area('Why it matters (optional)','note',draft.goalEdit?goal().note:'','A weekend with time to breathe.')+submit('Save my goal','leaf'))}`;
case 'goal-detail':return `${header('Your little freedom','add-goal','edit')}<div class="center">${art('escape','small')}${title('Money actually set aside',esc(state.goalName),'Self-reported confirmations · No bank connection')}<div class="metric" style="font-size:49px;margin:20px 0 5px">${money(goalAmount())}</div><p class="small muted">of ${money(state.goalTarget)} · ${Math.round(goalAmount()/state.goalTarget*100)}% of your goal</p></div><div class="spacer"></div>${progress(goalAmount()/state.goalTarget*100)}<div class="section-row"><h2 class="section-title">Confirmed contributions</h2><span class="tiny muted">Manual confirmations</span></div>${goal().contributions.map(c=>receipt(esc(c.date),money(c.amount))).join('')||'<p class="small muted">No contributions yet. Every goal starts somewhere.</p>'}<div class="spacer"></div>${btn('I set some money aside','set-aside','','plus')}<p class="footer-note">Your contributions are confirmations, not transactions.</p>`;
case 'set-aside':return `${header('A real small step')}${title('Keep the totals honest','Did you actually<br>set money <em>aside?</em>','Only confirm an amount after moving it into your own savings, or intentionally reserving it.')} ${form('set-aside',field('Amount ('+state.currency+')','amount','','number')+select('For my goal','goal',state.goals.map(g=>g.name),state.goalName)+select('What I did','method',['Moved it to my savings account','Reserved it in my own budget','Put it in a cash envelope'],'Moved it to my savings account')+`<div class="card mint-card"><p class="small muted">Confirming is a manual record. This prototype does not make a transfer.</p></div>`+submit('Confirm my contribution','check'))}`;
case 'set-aside-done':return `${header('A real little win')}<div class="center">${art('escape')}${title('Actually set aside','A little closer<br>to <em>what matters.</em>',money(draft.contribution||0)+' confirmed for '+esc(state.goalName)+'.')}<div class="card mint-card">${progress(goalAmount()/state.goalTarget*100)}<p class="small muted" style="margin-top:13px">${money(goalAmount())} of ${money(state.goalTarget)}</p></div>${btn('See my goal','goal-detail','','arrow')}${btn('Back to my day','today','ghost')}</div>`;
case 'insights':return `${topHome()}${title('Understand your rhythm','Patterns,<br>not <em>judgments.</em>','Sample data to illustrate the experience. Your own logs would shape these insights.')}<div class="segmented"><button class="${insightPeriod==='week'?'active':''}" data-action="insight-period" data-value="week">This week</button><button class="${insightPeriod==='month'?'active':''}" data-action="insight-period" data-value="month">This month</button></div><div class="two-col"><div class="card"><div class="overline">Cost skipped</div><div class="metric small">${money(state.skipped)}</div><div class="tiny muted">Not confirmed savings</div></div><div class="card mint-card"><div class="overline">Actually set aside</div><div class="metric small">${money(state.setAside)}</div><div class="tiny muted">Self-reported</div></div></div><div class="section-row"><h2 class="section-title">Moments you paused</h2><span class="chip">${insightPeriod==='week'?'9 this week':'23 this month'}</span></div><div class="chart" role="img" aria-label="${insightPeriod==='week'?'Sample pauses: Monday 1, Tuesday 2, Wednesday 0, Thursday 1, Friday 3, Saturday 2, Sunday 0':'Sample month: week 1 eight pauses, week 2 nine, week 3 four, week 4 two'}">${(insightPeriod==='week'?[['M',1],['T',2],['W',0],['T',1],['F',3],['S',2],['S',0]]:[['W1',8],['W2',9],['W3',4],['W4',2]]).map(([l,n],i)=>`<div class="chart-bar ${i===4?'active':''}" style="height:${n*(insightPeriod==='week'?28:10)+3}px"><b>${n}</b><span>${l}</span></div>`).join('')}</div><div class="card mint-card insight-callout">${icon('spark')}<span>${insightPeriod==='week'?'In this sample, 4 of 9 pauses followed social media browsing. A small boundary could help.':'In this sample month, 23 pauses created room for reflection. Notice the moments, rather than chasing a bigger number.'}</span></div>${listRow('What is behind the urge?','See trigger patterns and your own reflections.','trigger-insights','heart')}${listRow('My weekly reflection','One thing to keep. One thing to adjust.','weekly-review','book')}${listRow('My recorded progress','Check-ins that remain after a purchase.','progress-review','leaf')}`;
case 'trigger-insights':return `${header('Your urge patterns')}${title('A little understanding','Notice the<br><em>moments.</em>','Sample logs show when urges arrived. These are observations, not diagnoses.')}<div class="card"><div class="overline">9 sample pauses this week</div>${[['Social media',4],['Boredom',3],['Stress',2]].map(([t,n])=>`<div style="margin:19px 0"><div class="row between small" style="margin-bottom:9px"><span>${t}</span><strong>${n} pauses</strong></div>${progress(n/9*100)}</div>`).join('')}</div><div class="card mint-card"><div class="overline">Try a small experiment</div><h2 class="quote" style="margin:12px 0">Browse with a reason.<br>Leave with a pause.</h2><p class="small muted">Before opening a shopping-heavy feed, decide how long you’ll stay.</p></div>${state.reflections.length?`<div class="card"><div class="overline">Your latest demo reflection</div><p class="small" style="margin-top:10px">${esc(state.reflections.at(-1))}</p></div>`:''}${btn('Make a temptation plan','temptation-plan','','arrow')}`;
case 'weekly-review':return `${header('Weekly reflection')}${title('A gentle review','What did this<br>week <em>teach you?</em>','You don’t need to improve everything. One small adjustment is enough.')}<div class="card mint-card row between"><div><div class="overline">Sample week</div><div class="metric small">6 / 7</div><div class="tiny muted">Days you checked in</div></div>${icon('leaf')}</div>${form('weekly',area('One thing I’m proud of','proud','','A purchase I thought through. An urge I noticed.')+area('One thing I’ll try next week','next','','A small adjustment that feels realistic.')+submit('Keep this reflection','check'))}`;
case 'temptation-plan':return `${header('Before a tempting moment')}${title('Prepare, don’t panic','Make the plan<br>before the <em>sale.</em>','A countdown is someone else’s timeline. Your rules can be yours.')} ${form('temptation',field('The event or moment','event',draft.event||'Black Friday')+field('Date','date','2026-11-27','date')+area('What I actually need','needs',draft.needs||'Replace my worn-out winter boots. Nothing else.')+area('My boundary','boundary',draft.boundary||'Check my inventory first. Wait 48 hours. Keep within my allowance.')+submit('Save my plan','check'))}<p class="footer-note">Date-based local planning concept. No live sale detection or scheduled notification service.</p>`;
case 'buddy':return `${header('Your quiet circle')}${title('A little support','Buy less.<br><em>Together.</em>','One trusted person. A shared intention. No public feed to keep up with.')}<div class="buddy-orbs"><span class="avatar">A</span><span class="avatar">?</span></div><div class="card mint-card"><h2 class="quote">Small wins feel good<br>with someone cheering.</h2><p class="small muted" style="margin-top:14px">Share a challenge and occasional check-ins. Keep prices, notes and feelings private by default.</p></div>${btn('Create a buddy invite','invite','','users')}${btn('Share my own progress','share-card','ghost')}<p class="footer-note">Buddy accounts and delivery are future backend features.<br>This prototype lets you review the invitation.</p>`;
case 'invite':return `${header('A thoughtful invitation')}${title('You choose what to share','A quiet<br><em>invitation.</em>','Preview the invitation before sharing it yourself.')} ${form('invite',field('Buddy’s first name (optional)','name','','text','','Sam')+area('A personal message','message','I’m trying a little low-buy challenge. Want to cheer each other on?')+`<div class="card mint-card"><div class="overline">Shared by default</div>${checks(['Challenge name and dates','Check-in completed: yes or no'])}<p class="tiny muted">Amounts, wants and personal reflections remain private.</p></div>`+submit('Preview my invitation','arrow'))}<div id="invite-preview"></div>`;
case 'share-card':return `${header('Share a little win')}<div class="row between"><span class="small">Include my amounts</span><button class="switch ${shareAmounts?'on':''}" role="switch" aria-checked="${shareAmounts}" aria-label="Include amounts in share card" data-action="share-amounts"></button></div><div class="share-card">${brand()}<h1 class="hero-title">I’m making room<br>for <em style="color:var(--mint)">what matters.</em></h1>${art('garden')}<div class="chip">${icon('leaf')} ${checkinCount()} days I showed up</div>${shareAmounts?`<div class="row between small" style="margin-top:20px"><span>${money(state.skipped)} cost skipped</span><span>${money(state.setAside)} set aside</span></div>`:''}<p class="tiny" style="margin-top:20px">Buy less. Live more.</p></div>${action('Download my progress card','download-card','','download')}${action('Copy a caption','copy-caption','ghost','share')}<p class="footer-note">Your private notes and wishlist are never included.</p>`;
case 'settings':return `${header('Settings')}${title('A calmer experience','Make room for<br><em>your preferences.</em>','Working name: Lessly · Prototype v1.4')}<div class="card row"><span class="avatar" style="display:flex;align-items:center;justify-content:center">A</span><div><div class="item-title">Your local demo space</div><div class="item-sub">No account or sign-in required</div></div></div><div class="settings-section"><div class="eyebrow">Personal</div>${listRow('Currency & time price',state.currency+' · '+(state.rate?money(state.rate)+'/hour':'Rate hidden'),'profile','wallet')}${listRow('Gentle reminders','Choose the nudges that help.','notifications','bell')}${listRow('Things I own','Your enough collection.','owned','wardrobe')}${listRow('A life beyond shopping','My activities and low-energy alternatives.','joy-menu','sun')}${listRow('Allowance pockets','Personal budgets and carry-over.','pockets','wallet')}${listRow('Recurring spending review','Keep what is useful.','subscriptions','calendar')}${listRow('Purchase history','Context, policy dates and confirmed refunds.','purchase-history','bag')}${listRow('Payment commitments','My own balances and due dates.','commitments','wallet')}${listRow('Shopping friction','My manual environment checklist.','friction','lock')}${listRow('Meaningful goals','Money actually set aside.','goals','plane')}</div><div class="settings-section"><div class="eyebrow">Your app</div>${listRow('Privacy & data','Local storage, export and reset.','privacy','lock')}${listRow('Lessly Plus concept','A possible one-time upgrade.','plus','spark')}${listRow('Help & guidance','Understand the prototype.','help','help')}</div>`;
case 'notifications':return `${header('Gentle reminders')}${title('Only what helps','Nudges at<br><em>your pace.</em>','You can change your mind any time.')}<div class="card">${[['daily','Daily check-in','A quiet moment at 8:00 PM.'],['cooldown','A want is ready','Use each saved product’s own 3-day or 1-week review date.'],['weekly','Weekly reflection','A Sunday check-in with your patterns.']].map(([id,t,s])=>`<div class="list-row"><div class="grow"><div class="item-title">${t}</div><div class="item-sub">${s}</div></div><button class="switch ${state.reminders[id]?'on':''}" data-action="reminder" data-value="${id}" role="switch" aria-checked="${state.reminders[id]}" aria-label="${t}"></button></div>`).join('')}</div><div class="offline-banner">These are preference controls in a design prototype. They do not schedule or send notifications.</div>${action('Save my preferences','save-reminders','','check')}`;
case 'privacy':return `${header('Privacy & data')}${title('You’re in control','A private<br>little <em>space.</em>','The prototype stores your demo choices in this browser only.')}<div class="card">${checks(['No bank connection or payments','No sign-in or buddy delivery','No analytics or advertising scripts','No data sent to an app backend'])}<p class="small muted">Browser storage can be removed at any time. Export first if you want to keep the demo choices.</p></div>${action('Export my demo data','export','outline','download')}<div class="spacer"></div>${action('Reset the sample data','reset-demo','secondary','reset')}<div class="section-row"><h2 class="section-title">Before a real launch</h2></div><p class="subtitle">The production app needs a privacy policy, platform permission handling, secure account flows, and tested deletion/export controls. This is a design specification, not a published privacy policy.</p>`;
case 'plus':return `${header('A sustainable little app')}<div class="center"><div class="chip">${icon('spark')} Pricing concept · Not a checkout</div><h1 class="hero-title" style="margin-top:22px">A little more<br><em>room to grow.</em></h1>${art('garden','small')}<p class="subtitle">Keep the essentials free. Consider a one-time upgrade for deeper personal tools.</p></div><div class="card" style="margin-top:22px">${checks(['Unlimited personal challenges and goals','Longer pattern history and custom insights','More card styles and export formats'])}<div class="modal-note">Price and packaging are intentionally undecided. Core pause, check-in, and challenge features should remain useful without an upgrade.</div></div>${action('Join the concept waitlist','plus-interest','','heart')}<p class="footer-note">Demo feedback only. No purchase, subscription or email signup.</p>`;
case 'help':return `${header('A little guidance')}${title('Good to know','Simple tools.<br><em>Honest progress.</em>','This prototype is designed for a future mobile app.')}<div class="card"><h2 class="item-title">Cost skipped vs. actual savings</h2><p class="small muted">A skipped ${money(50)} purchase adds to skipped cost. It adds to money set aside only when you confirm that action.</p></div><div class="card"><h2 class="item-title">No-buy vs. low-buy</h2><p class="small muted">No-buy pauses chosen non-essential purchases. Low-buy lets you set an allowance. Both can include necessary exceptions.</p></div><div class="card"><h2 class="item-title">A thoughtful purchase is allowed</h2><p class="small muted">Log it honestly. Your progress and past check-ins remain. Review and adapt after an impulse purchase.</p></div><div class="card"><h2 class="item-title">What works in this prototype?</h2><p class="small muted">Navigation, forms, local logging, timer, preferences, manual savings, exports and card downloads. Accounts, bank services, notification delivery and buddy sync are not connected.</p></div><a class="button outline" href="app-idea.md" download>Download the full app idea ${icon('download')}</a><div class="spacer"></div><a class="button outline" href="design-spec.md" download>Download the UI/UX specification ${icon('download')}</a><div class="spacer"></div>${btn('Restart the introduction','welcome','ghost')}`;
case 'empty':return `${header('Your waiting room')}<div class="center empty-art">${art('companion')}${title('No wants waiting','A little<br><em>breathing room.</em>','You don’t need to fill this space. If something catches your eye, it can wait here.')}<div class="spacer"></div>${btn('Save my first product','add-item','','plus')}${btn('Enjoy what I already own','owned','ghost')}</div>`;
case 'offline':return `${header('A quiet connection')}<div class="offline-banner row">${icon('wifi')} You’re offline · Design state preview</div>${title('Still your space','Keep going.<br><em>We’ll wait.</em>','Your check-ins, rules and waiting room are designed to work locally.')}<div class="card">${checks(['Today’s check-in stays on your device','Your pause timer still works','Buddy updates would sync when connected'])}</div><div class="modal-note">Offline-first behavior is a production requirement. This static prototype is not an installed offline app.</div><div class="spacer"></div>${btn('Check in locally','check-in','','check')}${btn('Return to Today','today','ghost')}`;
case 'error':return `${header('A small interruption')}<div class="error-banner row">${icon('help')} We couldn’t sync your buddy update.</div>${title('No need to start over','Your progress<br>is <em>still here.</em>','Your check-in is saved locally. Try syncing again when the connection is steady.')}<div class="card"><div class="overline">Saved on this device</div><div class="row" style="margin-top:12px">${icon('check')}<span class="small">Today’s check-in and reflection</span></div></div>${action('Try again','retry','','reset')}${btn('Continue without syncing','today','ghost')}<p class="footer-note">Recoverable error preview. No sync service is connected.</p>`;
default:return header('Your space')+title('Lessly','A little <em>space.</em>');}}
function formatTime(n){return `${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`}
const featureNotes={
today:['A calm command center','A glance at your choices, a clear invitation to pause, and a small daily check-in.','Skipped cost and real money set aside stay separate. A wishlist price never becomes “savings” automatically.'],
timer:['Space before the checkout','A real 90-second timer creates a tangible moment between an urge and a decision.','The timer can pause or finish early. Leaving the screen pauses it. Motion respects reduced-motion settings.'],
workHours:['The price in your time','An optional take-home hourly rate turns an abstract price into a personal perspective.','This is an estimate for reflection. It is not an affordability decision or financial recommendation.'],
owned:['Enough, made visible','A small manual inventory helps you remember the good things that are already yours.','Category matching offers alternatives from your own list rather than invented recommendations.'],
recovery:['A return, not a punishment','A kind recovery flow helps you reflect after an unplanned purchase and choose one next step.','Rolling consistency keeps showing up meaningful. Purchases do not erase your history.'],
setAside:['Honest, meaningful progress','Only a manual confirmation adds money to the goal. No transfers are made by the app.','The distinction between cost skipped and money actually reserved is present throughout the experience.'],
temptationPlan:['Before the countdown','Prepare a need list and a boundary before a sale or a personally tempting event.','Your own rules get priority over someone else’s urgency. Planning is manual in this prototype.'],
buddy:['A quiet circle','One trusted person can make a personal challenge feel less lonely, without adding another feed.','Privacy-first sharing is specified. Invites, accounts and delivery are concept flows without a backend.']};
function noteFor(id){if(id==='timer')return featureNotes.timer;if(id==='work-hours'||id==='intro-clarity')return featureNotes.workHours;if(['owned','owned-detail','add-owned','compare-owned'].includes(id))return featureNotes.owned;if(id.startsWith('recovery'))return featureNotes.recovery;if(id.startsWith('set-aside')||id.startsWith('goal'))return featureNotes.setAside;if(id==='temptation-plan')return featureNotes.temptationPlan;if(['buddy','invite','share-card'].includes(id))return featureNotes.buddy;return featureNotes.today;}
function renderScreen(id){return decorateScreen(id,renderBaseScreen(id));}
function render(){document.getElementById('studio').classList[motionEnabled&&!systemReducedMotion?'remove':'add']('motion-off');if(screen!=='timer')stopTimer();updateCooldowns();const current=screens.find(s=>s.id===screen),idx=screens.indexOf(current),note=noteFor(screen);document.title=`${view==='prototype'?current.title:view==='library'?'All screens':'Brand & system'} — Lessly`;const studioHeader=`<header class="studio-header"><div class="brand"><span class="brand-mark">${icon('leaf')}</span>lessly <sup>DESIGN STUDIO</sup></div><nav class="studio-links" aria-label="Design review"><button data-view="prototype" class="${view==='prototype'?'active':''}">Prototype</button><button data-view="library" class="${view==='library'?'active':''}">All ${screens.length} screens</button><button data-view="brand" class="${view==='brand'?'active':''}">Brand & system</button></nav><div class="studio-badge"><span class="dot"></span> Visual edition 03 · Complete journeys</div></header>`;
const rail=`<aside class="rail"><div class="eyebrow">The complete experience</div><h2>${screens.length} screens. One calmer app.</h2><label class="search">${icon('search')}<span class="sr-only">Find a screen</span><input id="screen-search" type="search" value="${esc(search)}" placeholder="Find a screen…"></label><nav class="screen-list" aria-label="All app screens">${renderRail()}</nav><div class="tiny muted" style="margin-top:16px">Built for a solo indie developer.<br>Designed for US, UK & EU audiences.</div></aside>`;
const phone=`<main class="stage"><div class="stage-heading"><h1>${String(idx+1).padStart(2,'0')} / ${current.title}</h1><span>${current.group}</span><button class="mobile-index" data-view="library">Screen index ${icon('chevron')}</button></div><div class="phone phone-${screen}"><div class="statusbar"><span>9:41</span><span class="island" aria-hidden="true"></span><span class="status-icons">${icon('signal')}${icon('wifi')}${icon('battery')}</span></div><div class="app-content content-enter screen-${screen}" id="app-content" data-screen="${screen}">${renderScreen(screen)}</div>${navScreens.includes(screen)?bottomnav():''}<span class="home-indicator" aria-hidden="true"></span></div><div class="review-controls">${motionControl()}<button data-action="previous">${icon('back')} Previous screen</button><button data-go="welcome">${icon('reset')} Start walkthrough</button><button data-action="next">Next screen ${icon('arrow')}</button></div></main>`;
const notes=`<aside class="notes"><div class="eyebrow">Design intention</div><h2>${note[0]}</h2><p>${note[1]}</p><div class="note-label">${icon('spark')} A meaningful extra</div><p>${note[2]}</p><div class="note-line"><div class="eyebrow">Try the experience</div>${[['Create a personal challenge','challenge-type'],['Add a want, then reflect','add-item'],['Take a 90-second pause','trigger'],['Confirm a real contribution','set-aside']].map(([l,s],i)=>`<button class="flow-step" data-go="${s}" style="background:none;padding:0;text-align:left"><span class="number">${i+1}</span>${l}${icon('chevron')}</button>`).join('')}</div><div class="note-line"><div class="eyebrow">A reviewable prototype</div><p style="margin-top:9px">All screens are navigable. Your demo changes save locally. Auth, payments, buddy sync and notification delivery are future integrations.</p><a class="text-link" href="design-spec.md" download style="display:inline-flex;align-items:center;gap:6px;margin-top:15px">UI/UX specification ${icon('download')}</a></div></aside>`;
document.getElementById('studio').innerHTML=studioHeader+(view==='prototype'?`<div class="studio-layout">${rail}${phone}${notes}</div>`:view==='library'?`<div class="studio-layout gallery-layout">${rail}${renderLibrary()}</div>`:renderBrand());}
function renderRail(){return groups.map(([g,items])=>{const filtered=items.filter(([id,t,d])=>(t+' '+g+' '+d).toLowerCase().includes(search.toLowerCase()));if(!filtered.length)return '';return `<div class="group-heading"><span>${g}</span><span>${items.length}</span></div>${filtered.map(([id,t])=>`<button class="screen-link ${screen===id?'active':''}" data-go="${id}" ${screen===id?'aria-current="page"':''}><span>${String(screens.findIndex(s=>s.id===id)+1).padStart(2,'0')}</span><span>${t}</span></button>`).join('')}`;}).join('')||'<p class="small muted">No screens match that search.</p>';}
function galleryScreens(){const q=search.trim().toLowerCase();return screens.filter(s=>(galleryGroup==='All'||s.group===galleryGroup)&&(!q||(s.title+' '+s.description+' '+s.group).toLowerCase().includes(q)))}
function galleryFilters(){return ['All',...groups.map(g=>g[0])].map(g=>`<button data-action="gallery-group" data-value="${esc(g)}" class="${g===galleryGroup?'active':''}" aria-pressed="${g===galleryGroup}">${g}</button>`).join('')}
function renderGalleryCards(){return galleryScreens().map(s=>`<article class="library-card"><button class="gallery-card-head" data-go="${s.id}"><span>${String(screens.indexOf(s)+1).padStart(2,'0')}</span><b>${s.title}</b></button><div class="gallery-phone-wrap" role="button" tabindex="0" data-go="${s.id}" aria-label="Explore ${s.title}"><div class="phone gallery-phone phone-${s.id}" aria-hidden="true" inert><div class="statusbar"><span>9:41</span><span class="island"></span><span class="status-icons">${icon('signal')}${icon('wifi')}${icon('battery')}</span></div><div class="app-content screen-${s.id}">${renderScreen(s.id)}</div>${navScreens.includes(s.id)?bottomnav(s.id):''}<span class="home-indicator"></span></div></div></article>`).join('')||`<div class="gallery-empty"><h2>No screens match.</h2><p>Try a different search or journey.</p><button class="button outline" data-action="clear-gallery">Show all screens</button></div>`}
function renderLibrary(){return `<main class="library"><div class="gallery-title"><div class="eyebrow">THE COMPLETE EXPERIENCE</div><h1>Every moment, considered.</h1><p>Browse complete screens. Select one to explore its interactions.</p><div class="gallery-tools"><span id="gallery-result-count">${galleryScreens().length} of ${screens.length} screens</span>${motionControl()}<a href="design-spec.md" download>UI/UX specification ${icon('download')}</a></div><nav class="gallery-filters" aria-label="Filter screens by journey">${galleryFilters()}</nav></div><div class="library-grid" id="gallery-grid">${renderGalleryCards()}</div></main>`;}
function renderIllustrationGallery(){return `<section class="brand-tile asset-showcase"><div class="row between"><div><div class="eyebrow">Original art direction</div><h2>Seven scenes. One little world.</h2><p class="subtitle">Original transparent illustrations for pauses, recovery, goals, and enjoying what you own.</p></div>${motionControl()}</div><div class="asset-grid">${Object.entries(illustrationSet).map(([key,[file,alt]])=>`<article class="asset-card">${art(key)}<h3>${file.replaceAll('-',' ')}</h3><p>${alt}</p><a href="assets/${file}.webp" download>Download asset ${icon('download')}</a></article>`).join('')}</div></section>`}

function renderBrand(){return `<main class="brand-page"><div class="eyebrow">Working brand / Visual edition 03</div><h1 style="margin-top:10px">Less pressure.<br><em>More personality.</em></h1><p class="subtitle" style="margin-top:13px">Lessly is a temporary name for this concept. Calm, expressive and quietly optimistic.</p><div class="brand-grid"><section class="brand-tile brand-hero">${brand()}<h2 class="hero-title">Buy less.<br>Live <em style="color:var(--mint)">more.</em></h2>${art()}<p class="small" style="color:#d4dfca">A little less. A little lighter.</p></section><div class="stack"><section class="brand-tile"><h2>A palette with room to breathe</h2><div class="palette">${[['Forest','#183F35'],['Sprout','#D2E9BD'],['Clay','#F3AD91'],['Cream','#F8F7F0']].map(([n,c])=>`<div class="swatch"><i style="background:${c}"></i>${n}<br><span class="muted">${c}</span></div>`).join('')}</div></section><section class="brand-tile"><h2>Editorial warmth. Everyday clarity.</h2><div class="brand-type">A calmer <em>choice.</em></div><p class="subtitle">Bold system sans for clear headings and controls. Georgia italics for a few warm accents. Local fonts keep the prototype fast and self-contained.</p></section><section class="brand-tile"><h2>Motion with a purpose</h2><p class="subtitle">Staggered screen reveals, drifting sculptural artwork, growing progress bars, responsive presses and a breathing pause studio. Reduced motion removes decorative animation.</p></section></div></div><div class="principles">${[['heart','Kind by default','No broken-streak guilt. Purchases are part of life. Recovery is a real flow.'],['wallet','Honest about money','Cost skipped, spending logged, and money actually reserved have distinct labels.'],['leaf','Useful beyond the trend','Personal rules, a pause ritual, your own inventory, and meaningful goals create a daily reason to return.']].map(([i,t,d])=>`<div class="card">${icon(i)}<h3>${t}</h3><p>${d}</p></div>`).join('')}</div>${renderIllustrationGallery()}</main>`;}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>el.classList.remove('visible'),3200);}
function stopTimer(){clearInterval(timerInterval);timerInterval=null;timerRunning=false;}
function runTimer(){if(timerRemaining<=0)timerRemaining=90;stopTimer();timerRunning=true;timerInterval=setInterval(()=>{timerRemaining=Math.max(0,timerRemaining-1);const t=document.getElementById('timer-time'),r=document.querySelector('.timer-ring');if(t)t.textContent=formatTime(timerRemaining);if(r)r.style.setProperty('--timer-angle',`${(90-timerRemaining)/90*360}deg`);if(timerRemaining===0){stopTimer();render();toast('Your little pause is complete. Reflect when you’re ready.')}},1000);}
function downloadFile(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function cardDownload(){const safe=esc;const amounts=shareAmounts?`<text x="70" y="842" font-size="22" fill="#d2e9bd">${safe(money(state.skipped))} cost skipped · ${safe(money(state.setAside))} set aside</text>`:'';const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="720" height="960" viewBox="0 0 720 960"><rect width="720" height="960" rx="45" fill="#183f35"/><text x="70" y="105" font-family="Georgia,serif" font-size="48" fill="#d2e9bd">lessly</text><text x="70" y="255" font-family="Georgia,serif" font-size="65" fill="#f8f7f0">I’m making room</text><text x="70" y="340" font-family="Georgia,serif" font-size="65" fill="#d2e9bd">for what matters.</text><path d="M360 670V480M360 590c-100 0-135-90-135-90 95-20 135 90 135 90Zm0-55c100 0 135-90 135-90-95-20-135 90-135 90Z" stroke="#d2e9bd" stroke-width="7" fill="#d2e9bd"/><path d="M295 650h130l-15 90H310Z" fill="#f3ad91"/><text x="70" y="800" font-family="Arial,sans-serif" font-size="25" fill="#f8f7f0">${checkinCount()} days I showed up</text>${amounts}<text x="70" y="902" font-family="Arial,sans-serif" font-size="19" fill="#9fbd91">Buy less. Live more.</text></svg>`;downloadFile('lessly-progress.svg',svg,'image/svg+xml');toast('Your progress card is ready to download.');}
async function copyCaption(){const text=`I’m making room for what matters. ${checkinCount()} days I showed up. Buy less. Live more. #LowBuy #NoBuyChallenge${shareAmounts?' '+money(state.skipped)+' purchase cost skipped; '+money(state.setAside)+' actually set aside.':''}`;try{await navigator.clipboard.writeText(text);toast('Caption copied. Share it wherever you like.')}catch{downloadFile('lessly-caption.txt',text,'text/plain');toast('Caption saved as a text file.')}}
function handleAction(name,value,el){if(handleCommunityAction(name,value,el))return;switch(name){
case 'gallery-group':if(value==='All'||groups.some(g=>g[0]===value)){galleryGroup=value;render();}break;
case 'clear-gallery':galleryGroup='All';search='';render();break;
case 'toggle-motion':if(!systemReducedMotion){motionEnabled=!motionEnabled;try{localStorage.setItem('lessly-motion',motionEnabled?'on':'off')}catch{}const root=document.getElementById('studio');root.classList[motionEnabled?'remove':'add']('motion-off');el?.setAttribute?.('aria-pressed',String(motionEnabled));for(const control of (typeof document.querySelectorAll==='function'?document.querySelectorAll('[data-action=toggle-motion]'):el?[el]:[])){control.setAttribute?.('aria-pressed',String(motionEnabled));control.innerHTML=icon(motionEnabled?'pause':'play')+(motionEnabled?'Motion on':'Motion off');}}break;
case 'back':back();break;
case 'previous':go(screens[(screens.findIndex(x=>x.id===screen)-1+screens.length)%screens.length].id);break;
case 'next':go(screens[(screens.findIndex(x=>x.id===screen)+1)%screens.length].id);break;
case 'intent':state.intent=value;persist();render();break;
case 'mood':state.mood=value;persist();render();break;
case 'challengeType':state.challengeType=value;persist();render();break;
case 'category':state.categories=state.categories.includes(value)?state.categories.filter(x=>x!==value):[...state.categories,value];persist();render();break;
case 'rule':state.rules=state.rules.includes(value)?state.rules.filter(x=>x!==value):[...state.rules,value];persist();render();break;
case 'categories-next':if(!state.categories.length){toast('Choose at least one category for your challenge.');return;}go('challenge-rules');break;
case 'begin-challenge':state.challengeCreated=true;state.challengeDays=parseInt(draft.duration||'30');state.spent=0;persist();go('challenge-detail');toast('Your personal challenge is ready.');break;
case 'filter':wishFilter=value;render();break;
case 'open-want':selectedWant=Number(value);selectedQuestions=[];go('item-detail');break;
case 'open-day':selectedDay=Number(value);go('day-detail');break;
case 'open-goal':selectGoal(value);go('goal-detail');break;
case 'open-owned':selectedOwned=Number(value);go('owned-detail');break;
case 'question':{const n=Number(value);selectedQuestions=selectedQuestions.includes(n)?selectedQuestions.filter(x=>x!==n):[...selectedQuestions,n];render();break;}
case 'delete-want':if(draft.deleteWant!==want().id){draft.deleteWant=want().id;el.textContent='Tap again to remove this want';toast('This only removes the item. It won’t add skipped spending.');return;}state.wants=state.wants.filter(x=>x.id!==selectedWant);draft.deleteWant=null;persist();go(state.wants.length?'wishlist':'empty');toast('Removed from your waiting room.');break;
case 'skip-want':{const w=want();if(!state.wants.some(x=>x.id===w.id)){toast('This is a sample item. Add your own want to log a choice.');go('add-item');return;}draft.skippedPrice=w.price;state.skipped+=w.price;state.wants=state.wants.filter(x=>x.id!==w.id);persist();go('skip-done');break;}
case 'extend-wait':case 'wait-three':case 'wait-week':{const w=want();if(!state.wants.some(x=>x.id===w.id)){go('add-item');return;}const hours=name==='wait-week'?168:name==='wait-three'?72:48;w.hours=hours;w.reviewIntervalHours=hours;w.status='Waiting';w.cooldownUntil=new Date(Date.now()+hours*3600000).toISOString();persist();go('item-detail');toast('Review moved to '+reviewDate(w)+'.');break;}
case 'trigger':state.trigger=value;persist();render();break;
case 'start-timer':timerRemaining=90;go('timer');runTimer();render();break;
case 'toggle-timer':if(timerRunning)stopTimer();else runTimer();render();break;
case 'save-pause':state.pauseEvents.push({trigger:state.trigger,before:state.urge,after:state.urgeAfter,date:new Date().toISOString()});state.reflections.push(`A ${state.trigger.toLowerCase()} urge: ${state.urge}/10 before, ${state.urgeAfter}/10 after a pause.`);persist();go('alternatives');toast('Your reflection is saved on this device.');break;
case 'use-owned':state.reflections.push('Rediscovered '+owned().name+'.');persist();go('today');toast('A small rediscovery. Enjoy what’s already yours.');break;
case 'reminder':state.reminders[value]=!state.reminders[value];persist();render();break;
case 'save-reminders':persist();go(draft.reminderFrom||'settings');toast('Preferences saved. This demo sends no notifications.');break;
case 'share-amounts':shareAmounts=!shareAmounts;render();break;
case 'download-card':cardDownload();break;
case 'copy-caption':copyCaption();break;
case 'export':downloadFile('lessly-demo-data.json',JSON.stringify({exportedAt:new Date().toISOString(),prototype:true,...state},null,2),'application/json');toast('Your local demo data has been exported.');break;
case 'reset-demo':if(!draft.confirmReset){draft.confirmReset=true;el.textContent='Tap again to reset all demo data';toast('This restores sample data. Export first to keep your changes.');return;}state=migrateCommunity(structuredClone(defaults));draft={};persist();go('today');toast('Sample data restored.');break;
case 'plus-interest':toast('Interest noted for this demo. No signup or payment was created.');break;
case 'retry':toast('Local data is safe. Live buddy sync is not connected in this prototype.');go('buddy');break;
case 'insight-period':insightPeriod=value;render();break;
case 'copy-invite':{const t=draft.inviteText||'';(navigator.clipboard?navigator.clipboard.writeText(t):Promise.reject()).then(()=>toast('Invitation copied. No message was sent.')).catch(()=>{downloadFile('lessly-invitation.txt',t,'text/plain');toast('Invitation saved. No message was sent.');});break;}
}}
function handleForm(formEl){const id=formEl.dataset.form,data=Object.fromEntries(new FormData(formEl).entries());const error=(msg,name)=>{formEl.querySelector('.error-text').textContent=msg;formEl.elements[name]?.focus();};const required=(name,label)=>{if(!String(data[name]||'').trim()){error(label+' is required.',name);return false;}return true;};const positive=(name,label,zero=false)=>{if(data[name]===''||!Number.isFinite(Number(data[name]))||Number(data[name])<(zero?0:0.01)){error('Enter '+(zero?'zero or a positive':'a positive')+' '+label+'.',name);return false;}return true;};
if(handleCommunityForm(id,data,error,required,positive))return;
switch(id){
case 'profile':if(data.rate!==''&&!positive('rate','hourly rate',true))return;state.currency=data.currency;state.rate=Number(data.rate)||0;persist();go(draft.profileFrom||'notification-primer');break;
case 'check-in':state.checked=true;state.checkInSpending=data.spending;state.checkInNote=data.reflection;state.checkins['2026-10-10']={mood:state.mood,spending:data.spending,note:data.reflection,sample:false};if(data.reflection)state.reflections.push(data.reflection);persist();go(data.spending==='An unplanned purchase'?'recovery':'check-in-done');break;
case 'rules':draft.customRule=data.customRule;go('challenge-budget');break;
case 'budget':if(!required('name','A challenge name'))return;if(state.challengeType==='Low-buy'&&!positive('budget','allowance',true))return;state.challengeName=data.name.trim();if(data.budget!==undefined)state.budget=Number(data.budget);draft.duration=data.duration;persist();go('challenge-review');break;
case 'edit-rules':if(!required('name','A challenge name')||!positive('budget','allowance',true))return;state.challengeName=data.name.trim();state.budget=Number(data.budget);state.rules=data.rules.split('\n').map(x=>x.trim()).filter(Boolean);persist();go('challenge-detail');toast('Your challenge now fits a little better.');break;
case 'add-item':case 'edit-item':if(!required('name','An item name')||!positive('price','price'))return;{const rawUrl=String(data.productUrl||'').trim(),url=safeProductUrl(rawUrl);if(rawUrl&&!url){error('Enter a valid http or https product link.','productUrl');return;}const isEdit=id==='edit-item',existing=isEdit?want():null,changeDate=!isEdit||data.cooldown&&data.cooldown!=='Keep current review date';const hours=changeDate?reviewDelays[data.cooldown||'3 days']:existing.reviewIntervalHours;if(changeDate&&!hours){error('Choose a supported review interval.','cooldown');return;}const timestamp=changeDate?new Date(Date.now()+hours*3600000).toISOString():existing.cooldownUntil;const item={id:isEdit?existing.id:newRecordId(),name:data.name.trim(),price:Number(data.price),category:data.category,note:data.note||'',productUrl:url,createdAt:isEdit?existing.createdAt:new Date().toISOString(),reminderEnabled:data.reminder==='enabled',reviewIntervalHours:hours,cooldownUntil:timestamp,status:changeDate?'Waiting':existing.status,hours:changeDate?hours:existing.hours,icon:({Clothing:'shoe',Skincare:'bottle',Home:'lamp',Books:'book',Tech:'lamp',Hobbies:'gift'})[data.category]||'bag'};if(isEdit)Object.assign(existing,item);else state.wants.push(item);draft.newWantName='';draft.newWantPrice='';draft.newWantUrl='';selectedWant=item.id;persist();go('item-detail');toast(isEdit?'Your saved product is updated.':'Product saved. Review on '+reviewDate(item)+'.');}break;
case 'rate':if(!positive('rate','hourly rate',true))return;state.rate=Number(data.rate);persist();render();toast('Your time perspective is updated.');break;
case 'purchase':if(!required('name','An item name')||!positive('amount','amount'))return;communityLogPurchase({name:data.name.trim(),amount:Number(data.amount),category:data.category,kind:data.kind,note:data.note,returnBy:data.returnBy||'',date:new Date().toISOString()});draft.exceptionPurchase=false;if(state.categories.includes(data.category))state.spent+=Number(data.amount);if(state.wants.some(x=>x.id===selectedWant)&&want().name===data.name.trim())state.wants=state.wants.filter(x=>x.id!==selectedWant);persist();go(data.kind==='Unplanned purchase'?'recovery':'challenge-detail');toast('Purchase logged honestly. Your progress stays.');break;
case 'recovery':state.trigger=data.trigger;draft.recoveryNote=data.note;state.reflections.push('Recovery: '+data.trigger+'. '+data.note);persist();go('recovery-plan');break;
case 'owned':if(!required('name','An item name'))return;{const item={id:newRecordId(),name:data.name.trim(),category:data.category,condition:data.condition||'Ready to rediscover',remaining:100,useStatus:'In use',icon:({Clothing:'shoe',Skincare:'bottle',Home:'lamp',Books:'book'})[data.category]||'bag'};state.owned.push(item);selectedOwned=item.id;persist();go('owned-detail');}break;
case 'goal':if(!required('name','A goal name')||!positive('target','goal amount'))return;if(draft.goalEdit){Object.assign(goal(),{name:data.name.trim(),target:Number(data.target),note:data.note})}else{const g={id:newRecordId(),name:data.name.trim(),target:Number(data.target),amount:0,note:data.note,contributions:[]};state.goals.push(g);selectedGoal=g.id;}selectGoal(selectedGoal);persist();go('goal-detail');break;
case 'set-aside':if(!positive('amount','contribution'))return;selectGoal(state.goals.find(g=>g.name===data.goal).id);draft.contribution=Number(data.amount);state.setAside+=draft.contribution;goal().amount+=draft.contribution;goal().contributions.unshift({date:'Added in this demo',amount:draft.contribution});persist();go('set-aside-done');break;
case 'weekly':if(!String(data.proud+data.next).trim()){error('Add a small reflection in either field.','proud');return;}state.reflections.push('Proud: '+data.proud+' Next: '+data.next);persist();go('insights');toast('Your weekly reflection is saved.');break;
case 'temptation':if(!required('event','An event name')||!required('date','A date'))return;draft.event=data.event;draft.needs=data.needs;draft.boundary=data.boundary;state.temptationPlan=data;persist();go('challenges');toast('Your plan is saved locally. No reminder has been scheduled.');break;
case 'invite':if(!required('message','A message'))return;draft.inviteText=(data.name?'Hi '+data.name+', ':'')+data.message+' My challenge: '+state.challengeName+'.';document.getElementById('invite-preview').innerHTML=`<div class="card mint-card" style="margin-top:18px"><div class="overline">Invitation preview</div><p class="small" style="margin:13px 0">${esc(draft.inviteText)}</p>${action('Copy my invitation','copy-invite','outline','share')}<p class="tiny muted" style="margin-top:10px">No invite has been sent. Copy it to share yourself.</p></div>`;document.getElementById('invite-preview').scrollIntoView({behavior:'smooth',block:'end'});break;
}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-go],[data-view],[data-action]');if(!b)return;if(b.dataset.go){go(b.dataset.go);return;}if(b.dataset.view){view=b.dataset.view;render();return;}if(b.dataset.action)handleAction(b.dataset.action,b.dataset.value,b);});
document.addEventListener('keydown',e=>{const card=e.target.closest('.gallery-phone-wrap[role=button]');if(card&&(e.key==='Enter'||e.key===' ')){e.preventDefault();go(card.dataset.go);}});
document.addEventListener('submit',e=>{if(e.target.dataset.form){e.preventDefault();handleForm(e.target)}});
document.addEventListener('input',e=>{if(e.target.id==='screen-search'){search=e.target.value;const list=document.querySelector('.screen-list');if(list)list.innerHTML=renderRail();if(view==='library'){const grid=document.getElementById('gallery-grid'),count=document.getElementById('gallery-result-count');if(grid)grid.innerHTML=renderGalleryCards();if(count)count.textContent=galleryScreens().length+' of '+screens.length+' screens';}}if(e.target.dataset.range){const key=e.target.dataset.range;state[key]=Number(e.target.value);persist();const l=document.getElementById(key+'-label');if(l)l.textContent=state[key]+'/10';}});
window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(screens.some(s=>s.id===id)&&id!==screen){screen=id;view='prototype';render();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&timerRunning){stopTimer();if(screen==='timer')render();}});
render();
